import { DevServerContext } from '@teambit/bundler';
import { RspackConfigTransformer } from '@teambit/rspack.modules.rspack-config-mutator';

export type RspackDevServerOptions = {
  /**
   * path to load the rspack instance from
   */
  rspackModulePath?: string;

  /**
   * path to load the rspack dev server instance from.
   */
  rspackDevServerModulePath?: string;

  /**
   * name of the dev server.
   */
  name?: string;

  /**
   * context of the dev server execution.
   */
  devServerContext: DevServerContext;

  /**
   * array of transformers to apply on rspack config.
   */
  transformers?: RspackConfigTransformer[];
};
